import * as z from "zod/v4";
import { actionSchema, operationSchema, targetSchema, referenceSchema, contentFieldVersionSchema } from "./actions.js";
import { presentationStepSchema } from "./presentation.js";
import { sceneBoundsSchema, worldPointSchema } from "./spatial.js";
import {readBasisSchema,coverageSchema,snapshotSchema,actionResultSchema,readDataSchemas,methodDataSchemas,effectResultSchemas} from "./sdk-results.js";

const id=z.uuid(), text=z.string();
const observationScope=z.object({target:targetSchema,ids:z.array(text.min(1).max(120)).min(1).max(32).optional(),fields:z.array(z.enum(["preview","content","version","geometry"])).min(1).max(4).optional(),expand:z.array(z.enum(["incoming","outgoing","neighbors","container"])).max(4).optional(),bounds:sceneBoundsSchema.optional()}).strict();
const documentBytes=z.object({sourceVersion:contentFieldVersionSchema,offset:z.number().int().nonnegative(),maxBytes:z.number().int().min(1).max(1048576)}).strict();
const query=z.object({kind:z.enum(["observation","workspaceHeader","itemHeaders","itemHeader","itemLifecycle","workingSet","sceneWindow","scenePaintOrder","page","pageHeader","pageElement","pageInkActions","pageInkAction","documentHeader","document","documentState","documentDirectory","documentFile","documentFileBytes","documentProgram","documentStructure","boardItem","boardElement","boardContentRevision","ownerBoard","notebookPages","notebookDirectory","notebookPosition","spatialInk","presence","selection","attentionEvidence","contexts","contextEntries","actions","currentViewReceipt","pageVisionReceipt","targetRenderReceipt","renderRequests","delivery","actionSnapshots","runtime","codeFragment","codeFragments","storageUsage","actionHistoryPreflight"]),
  scope:observationScope.optional(),since:text.max(196608).optional(),next:text.max(196608).optional(),
  id:id.optional(),after:id.optional(),referenceID:id.optional(),revision:text.optional(),limit:z.number().int().positive().optional(),
  itemIDs:z.array(id).max(8).optional(),pageIDs:z.array(id).max(4).optional(),boardIDs:z.array(id).max(8).optional(),
  surfaces:z.array(z.object({kind:z.enum(["board","cover","codeFragment"]),ownerID:id.optional()}).strict()).max(8).optional(),
  pinnedIDs:z.array(id).optional(),bounds:sceneBoundsSchema.optional(),coverID:id.optional(),paintCursor:text.optional(),
  pageIndex:z.number().int().nonnegative().optional(),pages:z.array(z.json()).max(4).optional(),itemID:id.optional(),
  visibleRoot:text.optional(),contextID:id.optional(),elementID:text.optional(),fileID:text.optional(),sourceVersion:contentFieldVersionSchema.optional(),offset:documentBytes.shape.offset.optional(),maxBytes:documentBytes.shape.maxBytes.optional(),instanceID:text.min(1).max(120).optional(),programPath:text.min(1).max(1024).optional(),file:z.object({computer:id,project:text,root:text,path:text}).strict().optional()}).strict();
const action=z.object({summary:actionSchema.shape.summary,contextID:id.optional(),additionalOwners:z.array(targetSchema).max(32).optional(),
  references:z.array(referenceSchema).max(32).optional(),base:z.union([readBasisSchema,z.array(readBasisSchema).min(1).max(32)]),operations:z.array(operationSchema).min(1).max(512)}).strict();
const frame=z.object({x:z.number(),y:z.number(),width:z.number().positive(),height:z.number().positive()}).strict();
const image=z.object({kind:z.enum(["currentView","target","pageOverview","pageRegion","attention","scriptImage"]),id:id.optional(),contextID:id.optional(),referenceID:id.optional(),
  regionID:text.optional(),mode:z.enum(["faithful","ink"]).optional(),expectedSHA256:text.regex(/^[a-f0-9]{64}$/)}).strict();
const catalogue: Record<string,{input:z.ZodType;returns:string;example:string;old?:string[]}> = {
  help:{input:z.object({topic:text.optional()}).strict(),returns:"Index, or exact method input schema, result description and example. operations is a compact index of supported variants; operation/<name> gives one exact schema. interactive explains embedded notebook.ready(promise); execution explains terminal status and output pagination.",example:"await emit(await nb.help('operation/createDocument'));"},
  observe:{input:z.object({contextID:id.optional(),target:targetSchema.optional(),elementID:text.optional(),fileID:text.optional(),ids:observationScope.shape.ids,fields:observationScope.shape.fields,expand:observationScope.shape.expand,bounds:sceneBoundsSchema.optional(),limit:z.number().int().min(1).max(32).optional(),includeImage:z.boolean().optional(),since:text.max(196608).optional(),next:text.max(196608).optional()}).strict(),returns:"Snapshot of a bounded observation: data.objects, data.header, data.checkpoint, data.mode. coverage.next drains the same frozen scope; pass data.checkpoint as since only after complete. Fields/one-hop expansion/geometry remain Core-owned. Without target/contextID, data.selection reports the authenticated active UI choice (known or unknown); a selected element or set (kind:elements, authored elementIDs plus optional itemIDs and inkActionIDs; raw-only selection has objects:[], containers returns selected item headers) is read by exact physical target/IDs, even beyond the preview window. Selection grants no write scope. contextID reads only that historical source, never today’s camera/basis. includeImage:true returns current-view pixels only for an active known scene with a matching physical surface (otherwise current_scene_unknown/pending); for historical sources use attention({contextID,referenceID}), and for explicit targets use render. Missing source pixels are never replaced with the current view.",example:"let r=await nb.observe({target:args.target}); while(r.coverage.next) r=await nb.observe({target:args.target,next:r.coverage.next}); await emit(r);",old:["notebook_observe"]},
  read:{input:query,returns:"actionHistoryPreflight without id reads up to 64 accepted transaction markers (default 32); coverage.next is bound to the accepted read cut. With id=transaction UUID and revision=exact manifest SHA-256, it reports receipt closure evidence from that original manifest; referenceID optionally selects one receipt. unprovenClosure keeps coverage incomplete. Snapshot IDs are ephemeral, counters are exact decimal strings, and the report grants no migration/Undo authority. storageUsage reports bounded metadata from the current SQLite read cut: unique blobs, current records, all retained history, pending incoming indexes and up to 64 known outgoing peers. Categories deduplicate internally and can overlap. DB/WAL/SHM lengths are physical samples with a separate sampleStatus; coverage.complete is false for changed/incomplete samples or a truncated peer list. reachability is partial: unclassifiedBlobs are not proven orphans. This read never creates, migrates, cleans, checkpoints or vacuums storage. Its basis has no content owners and grants no write authority. documentProgram with document id, instanceID and programPath reads the pure executable sourceBasis, initialState and saved state/stateVersion without executing or staging code. Use that exact sourceBasis with setDocumentProgramState. pageInkActions with a page id returns a metadata directory (default 32, max 64) without sample/raster bodies; coverage.next continues UUID order, while sequence retains authored contact order. baseline reports an existing raster source, not editable strokes or OCR. pageInkAction with page id + elementID (stroke UUID) reads exactly one bounded measured source or null; both provide the same-snapshot page content/ink basis. Active pen/eraser source records are not final visible pixels: use pageMap/pageImage/regions for appearance. itemLifecycle with an item id returns its complete stored extent without loading page/document bodies, plus frozen workspace, actual parent and lifecycle basis. bodyRecordCount counts page/document/state records only, not a total deletion cost or mutation authority. Unseen source, ink, state, membership or child-board causal changes invalidate that extent; ordinary itemHeader does not provide it. selection returns known/unknown session identity, generation, physical surface and typed choice from the existing UI owner; its basis has no owners and grants no authority. Snapshot<T> selected by query.kind. data is one object or collection, never values[0]. basis contains exact owner versions from the SAME native snapshot, not mutation permissions. coverage.complete is explicit; next can be passed with the same kind to read. Stale continuation fails, without a hidden full rescan.",example:"const s=await nb.read({kind:'pageElement',id:args.pageID,elementID:args.elementID}); await emit(s.data);"},
  readMany:{input:z.object({queries:z.array(query).min(1).max(128),expectedCursor:text.optional()}).strict(),returns:"Snapshot<tuple> and coverages[] for the same ordered queries, captured in one WAL snapshot with a canonical merged basis. Each coverages[i].next continues that query. Conflicting basis versions cannot be merged.",example:"const s=await nb.readMany({queries:[{kind:'workspaceHeader'},{kind:'presence'}]}); await emit(s.data);"},
  board:{input:z.object({id:id.optional(),bounds:sceneBoundsSchema.optional(),limit:z.number().int().min(1).max(128).optional(),pinnedIDs:z.array(id).optional()}).strict(),returns:"Snapshot<SceneWindow>: data has header, boards, boardContentRevisions, items, totalMatches and truncated. basis includes the board and catalogue. Defaults to published viewport. For exhaustive spatial traversal use read scenePaintOrder.",example:"const scene=await nb.board({}); await emit(scene);",old:["notebook_read_board"]},
  notebook:{input:z.object({id,pageIndex:z.number().int().nonnegative().optional(),limit:z.number().int().min(1).max(4).optional(),visibleRoot:text.optional(),next:text.optional()}).strict(),returns:"Snapshot<PageDirectory>: data.header has item/visibleRoot; data.pages carries positions and versions. coverage.next continues through read({kind:'notebookDirectory',next}). Cover uses scenePaintOrder with coverID.",example:"await emit(await nb.notebook({id:args.notebookID,limit:4}));",old:["notebook_read_notebook"]},
  page:{input:z.object({id:id.optional(),elementID:text.optional()}).strict(),returns:"Snapshot<PageDocument> or Snapshot<PageElementRead|null> with elementID. A full page is explicit; one element never decodes unrelated bodies.",example:"const s=await nb.page({id:args.pageID,elementID:args.elementID}); await emit(s.data);",old:["notebook_read_page"]},
  document:{input:z.union([z.object({id:id.optional(),fileID:text.min(1).max(120),bytes:documentBytes}).strict(),z.object({id:id.optional(),fileID:text.min(1).max(120).optional()}).strict()]),returns:"Snapshot<DocumentDirectory> without fileID: entrypoint and file metadata/versions only, never all sources. With fileID returns Snapshot<DocumentFileRead|null>: exactly one file and its sourceVersion from the same native snapshot. Use that sourceVersion for put/patch/rename/remove. Low-level read({kind:'document',id}) explicitly reads the full source snapshot. A binary resource uses immutable SHA parts; source is empty. With fileID and bytes:{sourceVersion,offset,maxBytes}, returns only the selected base64 byte range plus the same sourceVersion, totalBytes and eof; stale versions fail. maxBytes is at most 1 MiB; prefer 65536 for emit because one output event is limited to 256 KiB. There is no default binary payload. notebook_import_document_resource stages a local file before ordinary putDocumentFile CAS. Paths are relative to the document, never device paths.",example:"const directory=await nb.document({id:args.documentID}); const file=directory.data.files.find(f=>f.path===directory.data.entrypoint); if(file) await emit(await nb.document({id:args.documentID,fileID:file.id}));"},
  documentStructure:{input:z.object({id:id.optional()}).strict(),returns:"Snapshot of the derived LaTeX structure for one exact source snapshot: entries identify sections, captions, labels, references and interactive instances by fileID, relative path, line and UTF-16 offset. It is navigation evidence, not an editable second document or proof of compilation.",example:"await emit(await nb.documentStructure({id:args.documentID}));"},
  documentCheck:{input:z.object({id,expectedRevision:text.min(1),pageIndex:z.number().int().min(0).max(9999).optional()}).strict(),returns:"Snapshot of a canonical exact-source render check. Use the document owner revision from the basis of a current directory/file read as expectedRevision; a reference revision is a different source identity. status ready requires the canonical print owner buildID; pending retains the existing render request, unverified means pixels lack a certified compile identity, and failed preserves native diagnostics. Error diagnostics make the check failed even when a readable PDF artifact exists; the artifact is retained for inspection. pageIndex selects the zero-based canonical page (default 0). programs lists exact-snapshot instanceID, sourceBasis when resolvable, status ready/failed/not_checked and scope startup. Only instances on that selected page are checked for startup: ready requires actual initialization evidence, failed reports source/configuration or startup failure, and others remain not_checked. No interaction, gesture or future animation is certified by startup. Before a compiled map exists, programs is empty. No second compiler, content mutation or camera movement is performed. A returned artifact belongs to this exact render receipt.",example:"const source=await nb.document({id:args.documentID}); const owner=source.basis.owners.find(o=>o.target.kind==='document'&&o.target.id.toLowerCase()===args.documentID.toLowerCase()); if(!owner) throw Error('Document owner unavailable'); const checked=await nb.documentCheck({id:args.documentID,expectedRevision:owner.revision}); await emit(checked); if(checked.data.artifact) await emitImage(checked.data.artifact);"},
  context:{input:z.object({id:id.optional(),after:id.optional(),revision:text.optional(),limit:z.number().int().min(1).max(64).optional()}).strict(),returns:"Snapshot<ContextDirectory|ContextPage>. coverage.next continues via read of contexts/contextEntries; history has its own readCursor and never supplies fresh content versions.",example:"await emit(await nb.context({id:args.contextID,limit:8}));",old:["notebook_read_context"]},
  attention:{input:z.object({contextID:id,referenceID:id}).strict(),returns:"Snapshot<Attention>: data.status is source_pixels, source_pixels_unavailable or pending. data.reference/payload/artifact preserve the original sent question; basis has no fabricated current owner versions.",example:"const s=(await nb.attention(args)).data; await emit(s); if(s.artifact) await emitImage(s.artifact);",old:["notebook_read_attention"]},
  code:{input:z.union([z.object({id}).strict(),z.object({file:query.shape.file.unwrap(),after:id.optional(),limit:z.number().int().max(64).optional()}).strict()]),returns:"Snapshot<CodeAnnotation|null> with id; data.fragment preserves reviewed text and identity, data.ink has addressed annotations, basis contains content/ink versions. file form returns a bounded fragment collection. Use notebook://code/<fragment.id> for navigation.",example:"await emit(await nb.code({id:args.fragmentID}));",old:["notebook_read_code_notes"]},
  search:{input:z.object({query:text.min(1).max(500),limit:z.number().int().min(1).max(100).optional(),filters:z.object({kinds:z.array(z.enum(["item","page","document","spatial"])).min(1).max(4).optional(),target:targetSchema.optional()}).strict().optional(),next:text.max(16384).optional()}).strict(),returns:"Snapshot<SearchResults>: data.results and data.total; coverage.next continues the same normalized query/filters in stable source-kind/address order. Source commits cause search_cursor_stale; restart explicitly. Presence/run events do not invalidate it. No handwriting OCR is inferred.",example:"await emit(await nb.search({query:'Transformer',limit:10}));",old:["notebook_search"]},
  reference:{input:z.object({target:targetSchema,elementID:text.optional()}).strict(),returns:"Snapshot {data,basis,coverage,cursor}. {revision}, source identity including composition geometry where applicable.",example:"await emit(await nb.reference({target:{kind:'page',id:args.pageID}}));"},
  referenceStatus:{input:z.object({reference:referenceSchema}).strict(),returns:"Snapshot {data,basis,coverage,cursor}. {status:current|changed|checking|review_required|target_missing,currentRevision?,fingerprint?}; strictly read-only. checking means prepare via render if pixels are needed.",example:"await emit(await nb.referenceStatus({reference:args.reference}));"},
  action:{input:z.object({actionID:id.optional(),actionVersion:text.optional(),next:text.optional(),contextID:id.optional(),limit:z.number().int().min(1).max(50).optional(),after:id.optional(),
    section:z.enum(["operations","revisions","changes","continuations","undo","snapshots"]).optional(),offset:z.number().int().nonnegative().optional(),pageSize:z.number().int().min(1).max(64).optional()}).strict(),returns:"Snapshot<ActionDetails> for actionID or a collection without it. Detail pages require actionVersion plus section/offset; ActionResult.next is version-bound and returns its changed page. Publication checks that exact version; it does not invent delivery/show confirmation.",example:"await emit(await nb.action({actionID:args.actionID,actionVersion:args.actionVersion,next:args.next}));",old:["notebook_action"]},
  render:{input:z.object({target:targetSchema,expectedRevision:text,expectedBuildID:text.min(1).optional(),region:frame.optional(),worldOrigin:worldPointSchema.optional(),pageIndex:z.number().int().nonnegative().optional()}).strict(),returns:"Snapshot {data,basis,coverage,cursor}. {status:pending,request} or target render receipt with exact source and artifact. Retain the same owner/revision and retry after nb.wait. For documents, expectedBuildID from documentCheck binds the displayed receipt to that exact compilation; a different or absent buildID fails build_changed. No camera movement.",example:"const r=(await nb.render(args)).data; await emit(r); if(r.artifact) await emitImage(r.artifact);",old:["notebook_render"]},
  pageMap:{input:z.object({id:id.optional(),drawingRevision:text.optional(),sinceDrawingRevision:text.optional()}).strict(),returns:"Snapshot {data,basis,coverage,cursor}. {status,drawingRevision,map}; map.regions names exact final-pencil crops. A cold source returns pending request.",example:"await emit(await nb.pageMap({id:args.pageID}));",old:["notebook_page_map"]},
  pageImage:{input:z.object({id:id.optional(),drawingRevision:text.optional(),mode:z.enum(["faithful","ink"]).optional()}).strict(),returns:"Snapshot {data,basis,coverage,cursor}. {status,drawingRevision,artifacts[]}; faithful pencil overview with grid, or ink-only.",example:"const r=(await nb.pageImage({id:args.pageID})).data; for(const a of r.artifacts??[]) await emitImage(a);",old:["notebook_render_page"]},
  regions:{input:z.object({id:id.optional(),drawingRevision:text,regionIDs:z.array(text).min(1).max(4),mode:z.enum(["faithful","ink"]).optional()}).strict(),returns:"Snapshot {data,basis,coverage,cursor}. {status,drawingRevision,artifacts[]} ordered exactly as requested regionIDs; an erased/stale region is refused.",example:"const r=(await nb.regions(args)).data; for(const a of r.artifacts??[]) await emitImage(a);",old:["notebook_render_region","notebook_render_regions"]},
  prepareTldraw:{input:z.object({source:text.max(1048576),namespace:id,selectedIDs:z.array(text.min(1).max(120)).max(512).optional(),scale:z.number().min(0.01).max(100).optional()}).strict(),returns:"Pure preparation of a tldraw clipboard HTML/envelope or TLContent into separate editable native elements. Returns items, sourceIDs (source ID to new ID), selectedIDs, elements, size, diagnostics and canInsert. Groups become independent children. Unsupported selected records block the entire fragment; select supported IDs and prepare again. No clipboard access, network, writes or destination authority. Use a stable namespace from nb.id. Read the destination and use its basis in one transaction of insertElement operations; values are each element without id, plus worldOrigin for a board. Adjust individual frames for composition, retaining binding IDs. Prepared basis has no owners and cannot authorize insertion.",example:"const copy = await nb.prepareTldraw({source:args.source,namespace:await nb.id('tldraw-fragment'),selectedIDs:args.selectedIDs}); await emit(copy.data);"},
  place:{input:z.object({target:targetSchema,expectedRevision:text,contextID:id.optional(),additionalOwners:z.array(targetSchema).max(32).optional(),worldOrigin:worldPointSchema.optional(),
    items:z.array(z.object({id:text,size:z.object({width:z.number().positive().max(2048),height:z.number().positive().max(2048)}).strict(),relativeTo:referenceSchema.optional(),relativeToID:text.optional(),direction:z.enum(["right","below","free"])}).strict()).min(1).max(32),
    movable:z.array(z.object({target:targetSchema,elementID:text.optional()}).strict()).max(32).optional()}).strict(),returns:"Snapshot<Placement> contains the proposal's exact basis and placements/moves. References/additionalOwners still control movement. Pending/full/budget failure produces no partial placement.",example:"const s=await nb.page({id:args.pageID}); await emit(await nb.place({target:{kind:'page',id:s.data.id},expectedRevision:s.basis.owners[0].revision,items:[{id:'note',size:{width:180,height:100},direction:'free'}]}));",old:["notebook_place"]},
  transaction:{input:z.object({key:text.min(1).max(120),action}).strict(),returns:"ActionResult {actionID,actionVersion,changed,basis,publication,next?}. base is a read basis or explicit array of bases; no expected array. Versions never refresh before a write. Missing components -> basis_incomplete, incompatible versions -> basis_conflict, wrong workspace -> basis_workspace_mismatch. Scope remains separate. Canonical small field values and exact after digests are frozen in the native commit with effect.value. Lifecycle changed events are appendPage {target,pageID,item} with the saved header or deletedItem {target,item} with the pre-action header; no page bodies or inverse records. Large changed sets use action({actionID,actionVersion,next}). Retry never substitutes latest state or later undo.",example:"const s=await nb.page({id:args.pageID,elementID:args.elementID}); await emit(await nb.transaction('label',{base:s.basis,summary:'Подпись',operations:[{kind:'updateElement',target:{kind:'page',id:args.pageID},id:args.elementID,values:{graphic:{label:'Обратная связь'}}}]}));",old:["notebook_apply"]},
  undo:{input:z.object({key:text.min(1).max(120),actionID:id}).strict(),returns:"ActionResult for the undo's own immutable version. Later human changes remain preserved. Lifecycle changed events report only actual restoreItem {target,item} or removePage {target,pageID,item?}; a preserved item/page emits no lifecycle event, and original operations are never replayed as results. preservedCount includes retained lifecycle owners; the exact-version undo detail section names them as {target,reason:'lifecycle_owner_continued'}, not invented field changes. Original ActionResult remains unchanged; detailed preserved addresses require actionID and this actionVersion.",example:"await emit(await nb.undo('undo-label',{actionID:args.actionID}));",old:["notebook_undo"]},
  point:{input:z.object({key:text.min(1).max(120),contextID:id.optional(),replyTo:id.optional(),references:z.array(referenceSchema.partial({id:true,revision:true})).min(1).max(32)}).strict(),returns:"Durable shared-context entry. Reply requires contextID and replyTo. Does not alter human camera/selection.",example:"await emit(await nb.point('source',{references:[{target:{kind:'page',id:args.pageID},label:'Рассмотренный лист'}]}));",old:["notebook_point"]},
  presentation:{input:z.object({id:id.optional()}).strict(),returns:"Snapshot {data,basis,coverage,cursor}. Current iPad view capability/presence, or exact presentation receipt by ID.",example:"await emit(await nb.presentation({}));"},
  present:{input:z.object({key:text.min(1).max(120),view:z.object({deviceID:id,sessionID:id,sequence:z.number().int().nonnegative(),nonce:id}).strict(),steps:z.array(presentationStepSchema).min(1).max(12)}).strict(),returns:"Sent/playing/completed/interrupted receipt. Use a step with attention:[currentReference] for material selection without moving camera or human selection; playing waits for the exact source to be installed. Creation/edits get automatic result feedback, so do not send a presentation after every transaction. Human contact interrupts; read presentation({id}) for actual shown state. No replay after reconnect.",example:"const view=(await nb.presentation({})).data; await emit(await nb.present('show',{view:view.view,steps:args.steps}));",old:["notebook_present"]},
  cancelPresentation:{input:z.object({key:text.min(1).max(120),id}).strict(),returns:"Native interruption receipt for the explicitly named presentation; does not change saved content.",example:"await emit(await nb.cancelPresentation('stop-show',{id:args.presentationID}));",old:["notebook_present"]},
  export:{input:z.object({moment:z.enum(["saved","presented"]).optional(),attention:z.object({contextID:id,referenceID:id}).strict().optional(),video:z.object({start:z.number().nonnegative(),end:z.number().positive(),framesPerSecond:z.number().int().min(1).max(60)}).strict().optional(),key:text.min(1).max(120),documentID:id,format:z.enum(["pdf","png","svg","html","package","mp4"]).optional(),instanceID:text.min(1).max(120).optional(),pageIndex:z.number().int().min(0).max(9999).optional(),pixelWidth:z.number().int().min(1).max(4096).optional()}).strict(),returns:"{status:queued,jobID,documentID,contentRevision,stateRevision,cutSHA256,moment:'saved'|'presented',options}. Presented moment requires attention:{contextID,referenceID} from an immutable submitted document selection. Only pixels certified by its installed native presentation owner are accepted, never regenerated evidence/cache. PNG exports that exact crop at its native extent; omit pixelWidth (or match it exactly), no pageIndex/instanceID/upscale. Missing, historical-without-provenance or stale evidence is an explicit error. Other formats require an explicitly paused checkpoint bound by that same capture to the selected instance/source/state, not an arbitrary running heap. SVG/HTML export that instance; whole-document PDF/package and canonical-page MP4 refuse other interactive instances without captured checkpoints. They reproduce the bound model, not exact screenshot bytes. MP4 requires instanceID, even pixelWidth and video:{start,end,framesPerSecond}; 1..60 FPS, integral 1..3600 frames in [start,end). It renders the chosen canonical page (pageIndex default 0, height padded white to even), H.264 without audio. The isolated author must register exportFrame(callback,{timeline:true}), rendering each explicit time from the same saved model/seed; no wall-clock capture or live rewind. Package exports one .notex ZIP containing the real source files, resources, manifest and saved state. Copy that one file and run submit.mjs document.notex; the native importer checks its SHA-256, paths, sizes and resources, then creates one new document in a transaction without executing programs. A matching optional compiled PDF is reused; stale derived data is discarded without losing source. HTML requires an instanceID and opens offline in a sandbox without installing or changing Notebook; packaged modules require a portable export. SVG requires instanceID and author notebook.exportFrame, returning a self-contained passive vector for the exact saved state in an isolated executor; it never silently embeds a PNG. PDF (default) keeps all pages vector; PNG exports one canonical page (pageIndex default 0, pixelWidth default 1600) including its isolated saved program frame. No silent downsampling: insufficient raster budget is an error. Queue acceptance reads source and state in one WAL snapshot. The native canonical print owner renders that immutable saved cut in isolation, never a later uncommitted live frame. Two admitted jobs; pinned embedded offline typesetter, same layout as paper. Source/formulas/SVG remain vector where possible; program regions are composited by the existing renderer with their local packages. Source or state changes before publication fail revision_conflict without replacing prior artifacts. The complete source tree is <=16 MiB, including resources; each text file is <=4 MiB. Composed PDF/assets stream through immutable 4 MiB parts and 1 MiB verification windows; only metadata crosses IPC. Export file metadata is <=8 MiB / 16384 parts, not a PDF byte limit.",example:"await emit(await nb.export('pdf',{documentID:args.documentID}));"},
  cancelExport:{input:z.object({key:text.min(1).max(120),jobID:id}).strict(),returns:"Durably cancels the explicitly named unfinished export, without altering previous artifacts or the live scene. Returns cancelled or the existing terminal job (saved wins after its final writer fence). Same key attaches to its receipt; exportStatus never restarts it.",example:"await emit(await nb.cancelExport('stop-pdf',{jobID:args.jobID}));"},
  exportStatus:{input:z.object({jobID:id}).strict(),returns:"Snapshot {data,basis,coverage,cursor}. Queued/running/saved/failed/interrupted/cancelled job. Saved receipt names the exact cutSHA256/stateRevision and immutable document.cut.json, options and primary artifact {path,sha256,byteCount,mimeType}; PDF also returns source, assets, sourceMap and syncTeX. packageSHA256 binds all files including the source/state cut. Status never re-executes or relabels an old cut as current.",example:"await emit(await nb.exportStatus({jobID:args.jobID}));"},
  wait:{input:z.object({milliseconds:z.number().int().min(0).max(1000)}).strict(),returns:"null after bounded async wait; does not hold interpreter CPU or native writer.",example:"await nb.wait({milliseconds:100});"},
  id:{input:z.object({key:text.min(1).max(120)}).strict(),returns:"Stable UUID derived from run_id and key, without a write.",example:"const id=await nb.id('diagram'); await emit(id);"},
  emit:{input:z.object({value:z.json()}).strict(),returns:"Durable output event with sequence. Output is paginated; no silent truncation.",example:"await emit({answer:42});"},
  emitImage:{input:z.object({artifact:image}).strict(),returns:"Durable reference to exact native pixels, returned as MCP image content.",example:"const r=(await nb.render(args)).data; if(r.artifact) await emitImage(r.artifact);"},
};

const operationDescriptions:Record<z.infer<typeof operationSchema>["kind"],string>={
  appendInkStroke:"Append native pen samples to a page, board, cover or code fragment.",
  convertInkToElement:"Convert existing pen strokes on the same physical owner into native geometry (1–16 strokes; up to 1024 for retained freehand, retaining exact measured relation bodies; authored primitives remain bounded to 65536 paint vertices and 100000 circular-sweep samples). Requires inkRevision. sourceInkIDs remain immutable; undo restores original ink. The graphic must be visible and use geometry representation.",
  insertElement:"Insert a native graphic, Markdown, a web program, or nativeText (page/board/cover) with a frame. Board elements require values.worldOrigin (tiled world anchor); their frame is relative to that anchor. Omit worldOrigin on cover/page elements, whose frame belongs to the surface.",
  updateElement:"Change a named element's source, style or frame.",
  setElementState:"Replace the JSON state of a named web element.",
  removeElement:"Remove one named element. Native graphics retain their identity and hide reversibly; source ink is not deactivated.",
  reorderElements:"Set the order of named elements in an owner.",
  putDocumentFile:"Create or replace one file. expectedVersion:null asserts absence; replacing a file requires its exact sourceVersion. Source is ordinary text or an immutable binary resource, never generated blocks.",
  patchDocumentFile:"Replace one UTF-16 range of a text file. expectedVersion, range and expectedText must all match; the transaction is atomic and preserves unrelated files.",
  renameDocumentFile:"Rename one file without changing its ID. Requires the exact file version; paths are document-relative. Update LaTeX includes in the same transaction when needed.",
  removeDocumentFile:"Remove one file by ID and exact sourceVersion. The entrypoint must remain present after the atomic transaction.",
  setDocumentProgramState:"Replace the JSON state of one interactive instance. Read nb.read({kind:'documentProgram',id:documentID,instanceID,programPath}) for current state and sourceBasis, without executing the program. programPath and sourceBasis identify the exact executable resources, independently of page geometry.",
  createNotebook:"Create a notebook at a board position.",
  createDocument:"Create a file-backed LaTeX document at a board position. entrypoint defaults to main.tex; omitted files creates the ordinary article template. Paper size and layout belong to the LaTeX source.",
  createBoard:"Create a board at a board position.",
  appendPage:"Append one blank page to a notebook's physical cover, inheriting its first page size. Optional id is a UUID; omission is generated once at admission and remains stable on retry. values is empty.",
  deleteItem:"Delete one item through its physical cover and actual containing board. Requires an explicit itemLifecycle read basis covering all stored content, not a visible preview. Only empty boards can be deleted: children are never deleted implicitly. When intended, explicitly delete the child owners before the board in the same transaction. The workspace retains its last item. No id or values fields beyond the empty values object.",
  renameItem:"Change one item's title. target is its containing board, never workspace; pass base from the ownerBoard read basis, which includes the board and root workspace catalogue.",
  moveItem:"Move one item to a tiled board position. A stack member is extracted as a free item; other members' placement registers are unchanged.",
  stackItems:"Stack two to five named items.",
};
const compositionRule="Geometry of existing content requires a source reference covering each moved subject, or its exact owner in action.additionalOwners. With contextID, only that context's stored references establish source scope; adding action.references cannot widen it. Without contextID, action.references establish it. Current selection/camera and expected revisions alone do not grant composition scope. New subjects created in the same action need no extra scope. A composition_scope rejection saves none of the atomic action.";
const moveExample=`const target = {kind:'board',id:args.boardID};
const owner = {kind:'cover',id:args.itemID,boardID:args.boardID};
const scene = await nb.board({id:args.boardID});
await emit(await nb.transaction('move-item', {
  summary:'Переместить выбранный предмет', additionalOwners:[owner],
  base:scene.basis,
  operations:[{kind:'moveItem',target,id:args.itemID,
    values:{center:{tileX:0,tileY:0,localX:100,localY:80}}}]
}));`;
const renameExample=`const owner = await nb.read({kind:'ownerBoard',id:args.itemID});
if (!owner.data) throw new Error('Item has no containing board');
await emit(await nb.transaction('rename-item', {
  summary:'Переименовать предмет', base:owner.basis,
  operations:[{kind:'renameItem',target:{kind:'board',id:owner.data},id:args.itemID,values:{title:args.title}}]
}));`;
const lifecycleOwner="Read nb.read({kind:'itemLifecycle',id:itemID}) explicitly. Use its data.target unchanged: a cover with the actual containing boardID, not the root board or a page. Pass the returned basis and declare the exact cover in additionalOwners unless the source context already covers it. This read grants no mutation scope; stale or missing lifecycle evidence is never refreshed during a write.";
const lifecycleExample=(kind:"appendPage"|"deleteItem")=>`const extent = await nb.read({kind:'itemLifecycle',id:args.itemID});
if (!extent.data) throw new Error('Item is missing');
await emit(await nb.transaction('${kind==="appendPage"?"append-page":"delete-item"}', {
  summary:'${kind==="appendPage"?"Добавить лист":"Удалить предмет"}', base:extent.basis, additionalOwners:[extent.data.target],
  operations:[{kind:'${kind}',target:extent.data.target,values:{}}]
}));`;
const filePatchExample=`const snapshot = await nb.document({id:args.documentID,fileID:args.fileID});
if (!snapshot.data) throw new Error('File is missing');
await emit(await nb.transaction('edit-source', {
  summary:'Исправить исходный текст', base:snapshot.basis,
  operations:[{kind:'patchDocumentFile',target:{kind:'document',id:args.documentID},id:args.fileID,
    values:{expectedVersion:snapshot.data.sourceVersion,range:args.range,expectedText:args.expectedText,source:args.source}}]
}));`;
const geometryScope:Partial<Record<z.infer<typeof operationSchema>["kind"],string>>={
  moveItem:"The operation target is the containing board. A stacked item is extracted at the requested center through the native unstack owner; this does not move the remaining members. The moved subject is {kind:'cover',id:itemID,boardID:boardID}; declare that cover in action.additionalOwners when no source context covers it. Listing only the board is insufficient. A context reference to this notebook's page also covers its physical carrier.",
  stackItems:"Declare each existing item's {kind:'cover',id:itemID,boardID:target.id} in action.additionalOwners unless source references already cover all carriers.",
  updateElement:"Changing frame or worldOrigin of an existing element requires scope for that element. Declare operation.target in action.additionalOwners, or reference its elementID/a source region that intersects its current geometry. Source/style-only edits do not add a geometry requirement.",
  reorderElements:"Every existing named element needs source scope, or declare operation.target in action.additionalOwners. Elements created earlier in this same action are exempt.",
};
const creationOwner="Creation changes the containing board and root workspace catalogue. nb.board returns both in snapshot.basis. Pass base:snapshot.basis. Newly created owners require no invented version; Core retains the same in-transaction rules.";
const createDocumentExample="const s=await nb.board({}); await emit(await nb.transaction('document',{summary:'Учебный документ',base:s.basis,operations:[{kind:'createDocument',target:{kind:'board',id:s.data.boardID},values:{title:'Пример',center:{tileX:0,tileY:0,localX:0,localY:0},entrypoint:'main.tex',files:[{id:'main',path:'main.tex',source:String.raw`\\documentclass{article}\\begin{document}Hello, LaTeX.\\end{document}`} ]}}]}));";
const operationDetails=Object.fromEntries(operationSchema.options.map(schema=>{
  const name=schema.shape.kind.value;
  return [name,{name,description:operationDescriptions[name],input:z.toJSONSchema(schema,{reused:"ref"}),
    ...(name==="renameItem"?{owner:"Find the containing board with nb.read({kind:'ownerBoard',id:itemID}). Use its UUID in operation.target, and the item UUID in operation.id. Use the returned snapshot.basis; it contains the board and workspace catalogue. A title-only edit needs no geometry scope.",example:renameExample}:{}),
    ...(name==="appendPage"||name==="deleteItem"?{owner:lifecycleOwner,example:lifecycleExample(name)}:{}),
    ...(["createDocument","createNotebook","createBoard"].includes(name)?{owner:creationOwner,
      ...(name==="createDocument"?{example:createDocumentExample}:{} )}:{}),
    ...(name==="patchDocumentFile"?{owner:"Use the addressed file sourceVersion, not a synthesized document version. UTF-16 offsets match JavaScript string offsets. Different files retain independent versions; stale same-file edits reject the entire transaction.",example:filePatchExample}:{}),
    ...(geometryScope[name]?{compositionScope:{rule:compositionRule,owner:geometryScope[name]},
      ...(name==="moveItem"?{example:moveExample}:{} )}:{}),
    relatedTopics:["transaction","examples",...(name==="putDocumentFile"||name==="createDocument"?["interactive"]:[])]}];
}));
const interactiveFiles=[
  {id:"counter-html",path:"programs/counter/index.html",source:'<button id="increment">Прибавить один</button> <output id="count"></output>'},
  {id:"counter-css",path:"programs/counter/style.css",source:"button,output{font:24px -apple-system,sans-serif}button{padding:12px}"},
  {id:"counter-js",path:"programs/counter/main.js",source:`const button = document.getElementById('increment');
const output = document.getElementById('count');
const draw = () => { output.textContent = String(notebook.state?.count ?? 0); };
button.addEventListener('click', () => {
  notebook.commit({count: (notebook.state?.count ?? 0) + 1});
  draw();
});
addEventListener('notebookstate', draw);
notebook.ready(Promise.resolve().then(draw));`}
];
const interactiveExample=`const snapshot = await nb.document({id:args.documentID,fileID:args.fileID});
if (!snapshot.data) throw new Error('File is missing');
const target={kind:'document',id:args.documentID};
const files=${JSON.stringify(interactiveFiles,null,2)};
await emit(await nb.transaction('counter', {
  summary:'Интерактивный счётчик', base:snapshot.basis,
  operations:[...files.map(({id,...file})=>({kind:'putDocumentFile',target,id,values:{...file,expectedVersion:null}})),
    {kind:'patchDocumentFile',target,id:args.fileID,values:{expectedVersion:snapshot.data.sourceVersion,
      range:args.range,expectedText:args.expectedText,
      source:String.raw\`\\NotebookInteractive[id=counter,width=\\linewidth,height=90bp]{programs/counter}\`}}]
}));`;
const terminalStatuses=["completed","failed","cancelled","interrupted"];
const polling="Resume with after_seq=next_seq while status is queued/running OR has_more=true. Stop only when status is completed/failed/cancelled/interrupted AND has_more=false. running + has_more=false is normal: the current output is drained, but the program can still emit or save effects.";
export const sdkInputs = Object.fromEntries(Object.entries(catalogue).map(([name,method])=>[name,method.input]));
export const sdkOutputs:Record<string,z.ZodType> = {
  ...Object.fromEntries(Object.entries(methodDataSchemas).map(([name,schema])=>[name,snapshotSchema(schema)])),
  ...effectResultSchemas,
  read:snapshotSchema(z.union(Object.values(readDataSchemas))),
  readMany:snapshotSchema(z.array(z.union(Object.values(readDataSchemas)))).extend({coverages:z.array(coverageSchema)}),
};
export const sdkReference = {
  apiVersion:2,
  methods:Object.fromEntries(Object.entries(catalogue).map(([name,value])=>[name,{...value,input:z.toJSONSchema(value.input,{reused:"ref"}),output:z.toJSONSchema(sdkOutputs[name]!,{reused:"ref"})}])),
  readData:Object.fromEntries(Object.entries(readDataSchemas).map(([kind,schema])=>[kind,z.toJSONSchema(schema,{reused:"ref"})])),
  common:{basis:z.toJSONSchema(readBasisSchema),coverage:z.toJSONSchema(coverageSchema),actionResult:z.toJSONSchema(actionResultSchema)},
  operations:{description:"Choose operation/<name> for one exact schema. transaction contains the complete atomic action schema with shared $defs.",
    items:Object.values(operationDetails).map(({name,description})=>({name,topic:`operation/${name}`,description}))},
  operationDetails,
  execution:{polling,terminalStatuses,
    languages:"start.language is javascript (default) or typescript; the language is never inferred and failed TS never falls back to JS. Both accept an async body with args, nb, emit and emitImage. TS uses the app's pinned TypeScript 7.0.2 CLI, strict/noEmitOnError and generated NotebookSDK declarations before the same QuickJS interpreter. No imports, triple-slash paths, user tsconfig, filesystem or network. Compiler/SDK identity is fixed at durable admission; retry attaches to the original source/language/args without recompilation, even after a compiler update. Diagnostics name notebook-user.ts source lines.",
    preparationLimits:"TS preparation runs outside the writer, on a separate compiler connection. Limits: source/JS 256 KiB, map 1 MiB, diagnostics 64 KiB, temporary files 4 MiB, sampled resident memory 512 MiB, sampled CPU 5 seconds, wall 10 seconds including XPC launch. The 30-second active-run deadline includes preparation. Cancellation closes the next-stage fence: late compiler output cannot start JS. Public MCP reply/output limits are unchanged.",
    effects:"Each key has one durable identity. saved is backed by a native receipt or accepted export job. notSaved is a proven rejection/absence and is terminal: repeating the same key returns its stored error without dispatch. Correct the request using a new key and fresh revisions. outcomeUnknown means a durable witness could not be read, or the effect was transient presentation; no automatic replay. Startup reconciles unfinished effects even after their JS run has ended.",
    operationErrors:"A native operation rejection keeps its code/message and includes operation:{index,kind,target,id?}. index is zero-based in action.operations; id is bounded to 120 characters. No operation values/source are echoed. It is available on the caught JS error and effects[].error. Action-wide failures (for example an obsolete expected revision) have no invented operation index. All operations remain atomic: a rejection saves none, including earlier operations.",
    cancellation:"Cancel closes admission and interrupts JavaScript. The writer orders cancel against terminal completion; an accepted cancel ends with status:'cancelled', error.code:'run_cancelled'. Already accepted native effects finish and remain inspectable in effects; new effects are refused. A run that completed before cancel stays completed. Resume until terminal status AND has_more=false.",
    deadline:"The Mac owns a 30-second user execution deadline, including XPC sandbox launch and await. Expiration gives failed/script_timeout and stops new SDK effects even if the worker never entered main. Already accepted effects drain into their receipts before terminal publication. Queued runs have not started this budget. Trusted normalization has its own 8-second deadline; a persisted PDF job has a separate 120-second compiler deadline. Neither queue needs the user worker to answer cancellation.",
    exampleScope:"MCP client orchestration, outside Notebook JavaScript. reply is the initial notebook_execute structuredContent; consume handles each output event. For response_pending retain its original run_id/after_seq and follow the reply_deadline recovery contract.",
    example:`const terminal = ${JSON.stringify(terminalStatuses)};
for (;;) {
  if (reply.status === 'error') throw new Error(reply.message);
  for (const event of reply.events) await consume(event);
  if (terminal.includes(reply.status) && reply.has_more === false) return reply;
  reply = await callNotebookExecute({op:'resume',run_id:reply.run_id,after_seq:reply.next_seq,wait_ms:1000});
}`},
  interactive:{description:"Embedded spatial and document programs share NotebookProgram/1: DOM plus notebook.state, notebook.commit(next), notebook.ready(promise), notebook.lifecycle(hooks). These are separate from the universal executor's nb API.",
    readiness:"Call notebook.ready(promise) while installing the program; resolve it only after the initial drawing and any asynchronous setup are complete. ready marks initial presentation readiness, not the end of future interaction. JavaScript without a declaration fails locally with program_completion_unknown; rejected or hung ready never counts as ready. Static markup does not need a declaration.",
    state:"notebook.commit(next) publishes complete JSON state; redraw locally after a click. Listen for the notebookstate event to redraw remote or restored state. This local commit is not itself a durable-save receipt.",
    lifecycle:"Register once with {pause, checkpoint, resume, dispose} functions. pause stops your clocks/worker/audio before checkpoint returns complete JSON parameters/playhead/seed for the shown model. The native owner confirms its writer before retirement. Failed checkpoints leave the runtime available for resume/retry. Async pause/checkpoint/resume receive {signal}; abort and late completion cannot publish. Each operation has a 4s budget; do not commit on every frame. dispose releases author resources. This is not a heap snapshot or a global timer scheduler.",
    requiredArgs:{documentID:"Read the document UUID from Notebook first.",fileID:"The LaTeX file to edit.",range:"Exact UTF-16 replacement range in that file.",expectedText:"The selected text in that range; empty for insertion."},files:interactiveFiles,example:interactiveExample,
    relatedTopics:["operation/putDocumentFile","operation/createDocument","transaction"]},
  examples:{
    createDocument:createDocumentExample,
    graphic:"insertElement: {kind:'graphic',source:'',frame:{x:20,y:20,width:100,height:100},graphic:{shape:'ellipse',style:{stroke:{red:0,green:0,blue:0},strokeWidth:2},label:'+',representation:'geometry',visible:true,sourceInkIDs:[]}}. Native shapes: ellipse, rectangle, triangle, diamond, plus, connector. Triangle/diamond/rectangle may carry vertices: 3/4 convex ordered points {x,y} normalized to [0,1] in frame; omit or set null for the canonical outline. cornerRadius sets circular rounding in owner points (null or 0 is sharp); the contour clamps it to fit adjacent edges. Connector bendPosition is signed (-1e6..1e6, default 0.5): outline clipping may leave the bend beyond the visible ends. bend moves it perpendicular. elbowAxis horizontal/vertical retains an elbow route when endpoints detach; omit for automatic axis selection. For a board add worldOrigin. updateElement accepts a graphic patch, e.g. {graphic:{label:'?'}}; sourceInkIDs cannot be patched. convertInkToElement uses the same payload with existing sourceInkIDs and requires inkRevision.",
    connector:"A graphic with shape:'connector' has connection:{start:{point:{x:0,y:0},binding:{elementID:'a',normalizedAnchor:{x:0.5,y:0.5},isExact:false,isPrecise:false}},end:{point:{x:100,y:0},binding:{elementID:'b',normalizedAnchor:{x:0.5,y:0.5},isExact:false,isPrecise:false}},bend:0,startArrowhead:'none',endArrowhead:'arrow',labelPosition:0.5}. Points are element-local; bindings address native nodes on the same owner. Moving nodes derives the connection without changing its authored frame. Missing or hidden bound nodes hide the link, never detach it. Patch connection fields independently, e.g. {graphic:{connection:{bend:40},label:'1:2'}}. Replace an endpoint with {point:{x:...,y:...}} to detach explicitly. Styles support stroke, strokeWidth and dash solid/dashed/dotted. Heads: none/arrow/triangle/square/dot/pipe/diamond/inverted/bar. Read page/board/boardElement returns graphicResolution:{state:'geometry',frame} or {state:'hidden'} or {state:'pending',dependencies}; frame is derived, while the authored element.frame and binding values remain unchanged. Hidden means this geometry is not shown, including an ink representation; it does not remove intent. Undo reports retained_dependency addresses for later links that protect earlier node creation/conversion.",
    nativeText:"insertElement on board: {kind:'nativeText',source:'Подпись',worldOrigin:{tileX:0,tileY:0,localX:0,localY:0},frame:{x:0,y:0,width:200,height:80},textStyle:{fontSize:24,weight:0.45,red:0.09,green:0.09,blue:0.08,alpha:1}}. For a page or cover omit worldOrigin and use surface-local frame coordinates. Omit textStyle to use native defaults.",
    interactive:interactiveExample,
    patchDocumentFile:filePatchExample
  }
};
